- [ ] Manually verify setting `State = VerificationStatus.Unverified` clears verification

## Summary

Gestalt IndexedDB queries were not W3C-shaped. Index methods took positional prefix values, `KeyRange` bounds were scalar fragments instead of full keys, and cursor keys were `repeated KeyValue`. Go exposed wire `IndexedDBQuery` builders while Python, TypeScript, and Rust kept legacy `KeyRange`-plus-values signatures.

This is a hard-breaking pre-1.0 change. The wire protocol now uses a single `IndexedDBQuery` (exact `KeyValue` or full-key `KeyRange`; absent means all records), cursor keys are one `KeyValue`, and the daemon applies W3C key ordering.

Some hand-written code is implemented for query ergonomics. 

## Interfaces

### Wire protocol

```protobuf
message IndexedDBQuery {
  oneof query {
    KeyValue key = 1;
    KeyRange range = 2;
  }
}
```

```diff
 message KeyRange {
-  TypedValue lower = 1;
-  TypedValue upper = 2;
+  KeyValue lower = 1;
+  KeyValue upper = 2;
   bool lower_open = 3;
   bool upper_open = 4;
 }

 message IndexQueryRequest {
   string store = 1;
   string index = 2;
-  repeated TypedValue values = 3;
-  optional KeyRange range = 4;
+  IndexedDBQuery query = 3;
+  optional uint32 count = 4;
 }

 message ObjectStoreRangeRequest {
   string store = 1;
-  optional KeyRange range = 2;
+  IndexedDBQuery query = 2;
+  optional uint32 count = 3;
 }

 message OpenCursorRequest {
   string store = 1;
-  optional KeyRange range = 2;
-  CursorDirection direction = 3;
-  bool keys_only = 4;
-  string index = 5;
-  repeated TypedValue values = 6;
+  string index = 2;
+  IndexedDBQuery query = 3;
+  CursorDirection direction = 4;
+  bool keys_only = 5;
 }

 message CursorEntry {
-  repeated KeyValue key = 1;
+  KeyValue key = 1;
   string primary_key = 2;
   Record record = 3;
 }

 message CursorKeyTarget {
-  repeated KeyValue key = 1;
+  KeyValue key = 1;
 }

 message CountResponse {
+  option (unwrap) = "count";
   int64 count = 1;
 }
```

### Query construction

```go
type KeyRange = client.KeyRange          // native sdkgen type, not protobuf
type Query = client.IndexedDBQuery
func Only(v any) *KeyRange
func Bound(lower, upper any, lowerOpen, upperOpen bool) *KeyRange
func LowerBound(v any, open bool) *KeyRange
func UpperBound(v any, open bool) *KeyRange
func ToQuery(query any) *Query
```
```python
def only(v: Key) -> KeyRange
def bound(lower: Key, upper: Key, lower_open: bool = False, upper_open: bool = False) -> KeyRange
def lower_bound(v: Key, open: bool = False) -> KeyRange
def upper_bound(v: Key, open: bool = False) -> KeyRange
```
```typescript
export type KeyScalar = number | string | Date | Uint8Array;
export type Key = KeyScalar | readonly Key[];
export function only(key: Key): KeyRange
export function bound(lower?: Key | null, upper?: Key | null, lowerOpen?: boolean, upperOpen?: boolean): KeyRange
export function lowerBound(key: Key, open?: boolean): KeyRange
export function upperBound(key: Key, open?: boolean): KeyRange
```
```rust
pub enum Key { Int(i64), Float(f64), Str(String), Date(SystemTime), Bytes(Vec<u8>), Array(Vec<Key>) }  // From<&str/i64/f64/Vec<u8>/...>
pub enum Query { All, Key(Key), Range(KeyRange) }  // From<KeyRange>; client methods take impl Into<Query>
impl KeyRange {
    pub fn only(key: impl Into<Key>) -> Self;
    pub fn bound(lower: impl Into<Key>, upper: impl Into<Key>, lower_open: bool, upper_open: bool) -> Self;
    pub fn lower_bound(key: impl Into<Key>, open: bool) -> Self;
    pub fn upper_bound(key: impl Into<Key>, open: bool) -> Self;
}
```

### Evaluation helpers

```go
func CompareKeys(a, b any) int
func KeyInRange(key any, kr *client.KeyRange) (bool, error)
func MatchQuery(key any, query *client.IndexedDBQuery) (bool, error)
```
```python
def compare_keys(left: Key, right: Key) -> int
def key_in_range(key: Key, kr: KeyRange) -> bool
def match_query(key: Key, query: Query) -> bool
```
```typescript
export function compareKeys(left: Key, right: Key): number
export function keyInRange(key: Key, kr: KeyRange | undefined): boolean
export function matchQuery(key: Key, query: Key | KeyRange): boolean
```
```rust
pub fn compare_keys(left: &serde_json::Value, right: &serde_json::Value) -> Ordering
pub fn key_in_range(key: &serde_json::Value, range: &KeyRange) -> bool
pub fn match_query(key: &serde_json::Value, query: &Query) -> bool
```

### Facade signatures

```diff
 // Go — Index (ObjectStore mirrors)
-Get(ctx, values ...any) (Record, error)
-GetKey(ctx, values ...any) (string, error)
-GetAll(ctx, r *KeyRange, values ...any) ([]Record, error)
-GetAllKeys(ctx, r *KeyRange, values ...any) ([]string, error)
-Count(ctx, r *KeyRange, values ...any) (int64, error)
-Delete(ctx, values ...any) (int64, error)
-DeleteRange(ctx, r *KeyRange, values ...any) (int64, error)
-OpenCursor(ctx, r *KeyRange, dir CursorDirection, values ...any) (Cursor, error)
-OpenKeyCursor(ctx, r *KeyRange, dir CursorDirection, values ...any) (Cursor, error)
+Get(ctx, query any) (Record, error)
+GetKey(ctx, query any) (string, error)
+GetAll(ctx, query any, count ...uint32) ([]Record, error)
+GetAllKeys(ctx, query any, count ...uint32) ([]string, error)
+Count(ctx, query any) (int64, error)
+Delete(ctx, query any) (int64, error)
+OpenCursor(ctx, query any, dir CursorDirection) (Cursor, error)
+OpenKeyCursor(ctx, query any, dir CursorDirection) (Cursor, error)
```
```diff
 # Python
-def get(self, *values: Any) -> dict
-def get_all(self, key_range: KeyRange | None = None, *values: Any) -> list
-def count(self, key_range: KeyRange | None = None, *values: Any) -> int
-def delete(self, *values: Any) -> int
+def get(self, query: Query = None) -> dict
+def get_all(self, query: Query = None) -> list
+def count(self, query: Query = None) -> int
+def delete(self, query: Query = None) -> int
```
```diff
 // TypeScript
-getAll(range?: KeyRange, ...values: Key[]): Promise<Record[]>;
-count(range?: KeyRange, ...values: Key[]): Promise<number>;
-delete(...values: Key[]): Promise<number>;
+getAll(query?: Key | KeyRange): Promise<Record[]>;
+count(query?: Key | KeyRange): Promise<number>;
+delete(query?: Key | KeyRange): Promise<number>;
```
```diff
 // Rust
-async fn get_all(&mut self, range: Option<KeyRange>, values: Vec<Value>) -> Result<Vec<Record>, _>
-async fn count(&mut self, range: Option<KeyRange>, values: Vec<Value>) -> Result<i64, _>
+async fn get_all(&mut self, query: impl Into<Query>, count: Option<u32>) -> Result<Vec<Record>, _>
+async fn count(&mut self, query: impl Into<Query>) -> Result<i64, _>
```
```diff
 // Go
-ContinueToKey(key *KeyValue) bool
+ContinueToKey(key any) bool
 // TypeScript
-continueToKey(key: KeyValue[]): Promise<boolean>
+continueToKey(key: Key): Promise<boolean>
```

### Removed

```diff
 // Go — KeyRange struct -> native sdkgen alias
-type KeyRange struct { Lower, Upper any; LowerOpen, UpperOpen bool }
-func (r *KeyRange) Includes(key any) bool
+type KeyRange = client.KeyRange
```
```diff
 // Go
-func QueryKey(key any) (*proto.IndexedDBQuery, error)
-func QueryRange(lower, upper any, lowerOpen, upperOpen bool) (*proto.IndexedDBQuery, error)
-func EncodeIndexedDBIndexValues(values []any) ([]byte, error)
-func DecodeIndexedDBIndexValues(data []byte, keyParts int) ([]any, error)
-func CursorKeyToProto(key any, indexCursor bool) ([]*proto.KeyValue, error)
+func CursorKeyToProto(key any) (*client.KeyValue, error)
```
```diff
 # Python:     _query_from_key_range / _query_from_index_args / _query_from_cursor
 # TypeScript: queryFromKeyRange / queryFromIndexArgs / queryFromCursorOpen
 # Rust:       query_from_key_range / query_from_index_args
+# replaced by one converter per SDK: queryToProto / _query_to_proto / query_to_proto
```

### Usage

```go
recs, _ := store.Index("by_owner").GetAll(ctx, []any{ownerKind, ownerID})

recs, _ := store.Index("by_vendor_date").GetAll(ctx, idb.Bound(
    []any{"claude_code", "2026-04-01"},
    []any{"claude_code", "2026-04-30"},
    false, false,
))

recs, _ := store.GetAll(ctx, nil)

cursor.ContinueToKey([]any{"claude_code", "2026-04-15"})
```

